targets.expr:
(
  instance:node_cpu_utilisation:rate5m{job="node-exporter", nodename=~"$Node"}
*
  instance:node_num_cpu:sum{job="node-exporter", nodename=~"$Node"}
/ ignoring (instance) group_left
  sum without (instance) (instance:node_num_cpu:sum{job="node-exporter", nodename=~"$Node"})
)

(
  instance:node_load1_per_cpu:ratio{job="node-exporter", nodename=~"$Node"}
/ ignoring (instance) group_left
  count without (instance) (instance:node_load1_per_cpu:ratio{job="node-exporter", nodename=~"$Node"})
)

(
  instance:node_memory_utilisation:ratio{job="node-exporter", nodename=~"$Node"}
/ ignoring (instance) group_left
  count without (instance) (instance:node_memory_utilisation:ratio{job="node-exporter", nodename=~"$Node"})
)

(
  instance_device:node_disk_io_time_seconds:rate5m{job="node-exporter", nodename=~"$Node" }
/ ignoring (instance, device) group_left
  count without (instance, device) (instance_device:node_disk_io_time_seconds:rate5m{job="node-exporter", nodename=~"$Node"})
)

( sum without (device) (
    max without () (
      node_filesystem_size_bytes{job="node-exporter", nodename=~"$Node", fstype!="tmpfs", fstype!="fuse.lxcfs"} 
    - node_filesystem_avail_bytes{job="node-exporter", nodename=~"$Node", fstype!="tmpfs", fstype!="fuse.lxcfs"}
    )
  ) 
/ ignoring (instance) group_left
  sum without (instance, device) (
    max without () (
      node_filesystem_size_bytes{job="node-exporter", nodename=~"$Node", fstype!="tmpfs", fstype!="fuse.lxcfs"}
    )
  )
)

(
  instance_device:node_disk_io_time_weighted_seconds:rate5m{job="node-exporter", nodename=~"$Node"}
/ ignoring (instance, device) group_left
  count without (instance, device) (instance_device:node_disk_io_time_weighted_seconds:rate5m{job="node-exporter", nodename=~"$Node"})
)

100 *
(
  1 -
  (
    max by (namespace, persistentvolumeclaim)
    (
      kubelet_volume_stats_available_bytes{
        job="kubelet",
        metrics_path="/metrics"
      }
    )
    /
    max by (namespace, persistentvolumeclaim)
    (
      kubelet_volume_stats_capacity_bytes{
        job="kubelet",
        metrics_path="/metrics"
      }
    )
  )
)
